import timeimport datetimeimport threadingimport serialimport serial.tools.list_portsfrom serial.tools.list_ports_common import ListPortInfoimport customtkinterimport matplotlib.pyplot as pltimport matplotlib.backends.backend_tkagg as plt_tkTICKS_PER_SECOND = 10000PKG_CYCLE = 64GUI_REFRESH_DELAY = 200OUTPUT_TRIGGER_CHANNEL_NUM = 6INPUT_CAPTURE_CHANNEL_NUM = 6TIMER_CAPTURE_CHANNEL_NUM = 16STAT_UPDATE_RATE = 0.5SIGNAL_MASK_SIZE = 5def packed_frame(frame: customtkinter.CTkFrame, padx: int | None = None, pady: int | None = None, fill=customtkinter.X, anchor: str | None = None, expand: bool = True, show: bool = True):    frame = customtkinter.CTkFrame(frame, fg_color=None if show else 'transparent')    if padx is None:        padx = 10 if show else 0    if pady is None:        pady = 10 if show else 0    frame.pack(padx=padx, pady=pady, fill=fill, anchor=anchor, expand=expand)    return frameclass App(customtkinter.CTk):    class Connection:        def __init__(self, frame: customtkinter.CTkFrame, parser, connect_callback, disconnect_callback):            self.serials_info: dict[str, ListPortInfo] = {}            self.serial: None | serial.Serial = None            self.parser = parser            self.connect_callback = connect_callback            self.disconnect_callback = disconnect_callback            self.list_refresh()            self.select_menu = customtkinter.CTkOptionMenu(frame, values=list(self.serials_info.keys()), command=self.serial_select_callback)            self.select_menu.pack(padx=10, pady=10, fill=customtkinter.X)            button_frame = packed_frame(frame, show=False)            self.refresh_button = customtkinter.CTkButton(button_frame, text="refresh", command=self.list_refresh)            self.refresh_button.pack(side=customtkinter.LEFT, padx=10, pady=10, fill=customtkinter.X)            self.connect_button = customtkinter.CTkButton(button_frame, text="connect", command=self.connect, width=360)            self.connect_button.pack(side=customtkinter.LEFT, padx=10, pady=10, fill=customtkinter.X)        def enable(self, state='normal'):            self.select_menu.configure(state=state)            self.connect_button.configure(state=state)            self.refresh_button.configure(state=state)        def disable(self):            self.enable('disabled')        def list_refresh(self):            self.serials_info = {f"{ser.product} {ser.device}": ser for ser in serial.tools.list_ports.comports() if ser.product is not None}            if hasattr(self, 'serials_select_menu'):                options = list(self.serials_info.keys())                self.select_menu.configure(values=options)                self.select_menu.set(options[0])            print('refresh devices list')        def connect(self):            if len(self.serials_info) == 0 or self.serial is not None:                return            if self.select_menu.get() not in self.serials_info:                self.list_refresh()                return            self.disable()            target_serial = self.serials_info[self.select_menu.get()]            print(f"connecting {target_serial.product} ({target_serial.device})")            self.serial = serial.Serial(port=target_serial.device, baudrate=115200, timeout=2.0)            self.connect_callback()            threading.Thread(target=self.serial_thread).start()        def serial_select_callback(self, _):            self.connect()        def serial_thread(self):            with open("log.log", 'w') as f:                while True:                    try:                        line = self.serial.readline()                        if len(line) == 0:                            print('Connection Out Time')                            break                        f.write(line.decode('utf-8'))                        self.parser(line)                    except serial.serialutil.SerialException:                        print('Connection Error')                        break            self.serial.close()            self.serial = None            time.sleep(5)            self.list_refresh()            self.enable()            self.disconnect_callback()        def send(self, payload: str):            self.disable()            checksum = 0            for b in payload.encode():                checksum = (checksum ^ b) & 0xff            print(f"${payload}*{checksum:02X}\r\n")            self.serial.write(f"${payload}*{checksum:02X}\r\n".encode())    class TransmitStatistic:        def __init__(self, frame: customtkinter.CTkFrame):            customtkinter.CTkLabel(frame, text="Transmit Success Rate").pack(side=customtkinter.LEFT, padx=10, pady=10)            self.lock = threading.Lock()            self.msg_idx: None | int = None            self.total_pkg: int = 0            self.pkg_loss: int = 0            self.pkg_progressbar = customtkinter.CTkProgressBar(frame, orientation="horizontal", width=160)            self.pkg_text = customtkinter.CTkLabel(frame, text="")            self.update()            self.pkg_progressbar.pack(side=customtkinter.LEFT, padx=10, pady=10)            self.pkg_text.pack(side=customtkinter.LEFT, padx=10, pady=10)        def __call__(self, msg_idx: int):            with self.lock:                self.total_pkg += 1                if self.msg_idx is not None:                    self.pkg_loss += (msg_idx + PKG_CYCLE - (self.msg_idx + 1) % PKG_CYCLE) % PKG_CYCLE                self.msg_idx = msg_idx        def reset(self):            self.msg_idx = None            self.total_pkg = 0            self.pkg_loss = 0        def update(self):            with self.lock:                rate = (1 - self.pkg_loss / self.total_pkg) if self.total_pkg > 0 else 0                detail = f"{self.pkg_loss} / {self.total_pkg:{('d' if self.total_pkg < 1e4 else '.1e')}}"            self.pkg_progressbar.set(rate)            self.pkg_text.configure(text=f"{rate:5.1%} loss: {detail}")    class CurrentTime:        def __init__(self, frame: customtkinter.CTkFrame):            self.lock = threading.Lock()            self.date_time: datetime.datetime | None = None            self.second_time: float = 0            customtkinter.CTkLabel(frame, text="Last System Time").pack(padx=10, pady=5, fill=customtkinter.X)            self.systim_line_frame = customtkinter.CTkFrame(frame, fg_color="transparent")            self.systim_line_frame.pack(padx=0, pady=10, fill=customtkinter.X)            customtkinter.CTkLabel(self.systim_line_frame, text='UTC Time').pack(side=customtkinter.LEFT, padx=10)            self.systim_utc_var = customtkinter.StringVar(self.systim_line_frame, '')            customtkinter.CTkEntry(self.systim_line_frame, textvariable=self.systim_utc_var, state='disabled', width=180, justify="center").pack(side=customtkinter.LEFT)            customtkinter.CTkLabel(self.systim_line_frame, text='Second Index').pack(side=customtkinter.LEFT, padx=10)            self.systim_second_var = customtkinter.StringVar(self.systim_line_frame, '')            customtkinter.CTkEntry(self.systim_line_frame, textvariable=self.systim_second_var, state='disabled', width=150, justify="center").pack(side=customtkinter.LEFT)        def __call__(self, date_time: datetime.datetime | None, second: float):            with self.lock:                if second > self.second_time:  # only record the latest time                    self.date_time = date_time                    self.second_time = second        def reset(self):            with self.lock:                self.date_time = None                self.second_time = 0        def update(self):            with self.lock:                utc_line = (f"{self.date_time:%Y/%m/%d %H:%M:%S.%f}"[:-3]) if self.date_time is not None else f"NaN"                second_line = f"{self.second_time:012.7f}"            self.systim_utc_var.set(utc_line)            self.systim_second_var.set(second_line)    class SystemState:        class SysStateLine:            _row: int = 1            def __init__(self, frame: customtkinter.CTkFrame, name: str, states: list[str], bit_shift: int):                customtkinter.CTkLabel(frame, text=name).grid(row=App.SystemState.SysStateLine._row, column=0, padx=10, pady=5, sticky="w")                self.states = states                self.segment = customtkinter.CTkSegmentedButton(frame, values=self.states, state='disabled')                self.segment.set(self.states[0])                self.segment.grid(row=self._row, column=1, padx=10, pady=5, sticky="nsew")                self.bit_shift = bit_shift                App.SystemState.SysStateLine._row += 1            def __call__(self, sys_state: int):                for i in range(len(self.states) - 1):                    if (sys_state & (1 << (self.bit_shift + i))) == 0:                        self.segment.set(self.states[i])                        return                self.segment.set(self.states[-1])        def __init__(self, frame: customtkinter.CTkFrame):            self.lock = threading.Lock()            self.sys_state: int | None = None            customtkinter.CTkLabel(frame, text="System State").grid(row=0, column=0, columnspan=2, padx=10, pady=5)            self.state_lines = [                App.SystemState.SysStateLine(frame, "Hot start", ['Cold start', 'Hot start'], 30),                App.SystemState.SysStateLine(frame, "Flash config", ['No config found in FLASH', 'Load config from FLASH'], 29),                App.SystemState.SysStateLine(frame, "Input Pulse", ['No Valid Pulse', 'Wait Pulse Ptable', 'Pulse Stable'], 0),                App.SystemState.SysStateLine(frame, "Main TIM Frequency", ['Bad / NaN', 'Fair', 'Good'], 2),                App.SystemState.SysStateLine(frame, "Main TIM Phase", ['Bad / NaN', 'Fair', 'Good'], 4),                App.SystemState.SysStateLine(frame, "RTC freq", ['Unsync', 'Coarse Synced', 'Fine Synced'], 6),                App.SystemState.SysStateLine(frame, "RTC phase", ['RTC Phase Unsync', 'RTC Phase Synced'], 8),                App.SystemState.SysStateLine(frame, "UTC input", ['No Input', 'Wait Stable', 'Input Stable', 'Time Stable'], 9),                App.SystemState.SysStateLine(frame, "UTC Timestamp", ['UTC Timestamp Unavailable', 'UTC Timestamp Available'], 12),            ]        def reset(self):            with self.lock:                self.sys_state = None        def __call__(self, sys_state: int | None):            with self.lock:                self.sys_state = sys_state        def update(self):            with self.lock:                if self.sys_state is not None:                    for state_line in self.state_lines:                        state_line(self.sys_state)    class SystemError:        def __init__(self, frame: customtkinter.CTkFrame, sender):            self.lock = threading.Lock()            self.sys_error: int = 0            self.sender = sender            self.error_mapping: dict[str, int] = {                "Non Maskable Interrupt": 0,                "Hard Fault": 1,                "Memory Management Fault": 2,                "Pre-Fetch / Memory-Access Fault": 3,                "Undefined Instruction / Illegal State": 4,                "HAL Error": 5,                "Peripheral Clock Error": 6,                "Main TIM Start Up Failure": 7,                "Tick Handling Overtime": 8,                "FLASH Error": 9,                "RTC Error": 10,                "UART Error": 11,                "Power Voltage Error": 29,                "Monitor Thread Error": 30,                "Tick Frequency Error": 31,            }            customtkinter.CTkLabel(frame, text="System Errors").pack(padx=10, pady=5, fill=customtkinter.X)            error_line = packed_frame(frame, show=False)            self.error_indicator = customtkinter.CTkButton(error_line, width=100)            self.error_indicator.pack(side=customtkinter.LEFT, padx=10, pady=10, fill=customtkinter.Y)            self.error_detail = customtkinter.CTkTextbox(error_line, width=260, height=60, text_color='red', state='disabled', wrap='none')            self.error_detail.pack(side=customtkinter.LEFT, padx=10, pady=10)            self.clear_error = customtkinter.CTkButton(error_line, text="Clear Error", width=100, command=self.clear_error_callback)            self.clear_error.pack(side=customtkinter.LEFT, padx=10, pady=10, fill=customtkinter.Y)            self.update()            self.disable()        def enable(self, state='normal'):            self.clear_error.configure(state=state)        def disable(self):            self.enable('disabled')        def reset(self):            with self.lock:                self.sys_error = 0        def __call__(self, sys_error: int):            with self.lock:                self.sys_error = sys_error        def update(self):            with self.lock:                self.error_detail.configure(state='normal')                self.error_detail.delete('1.0', customtkinter.END)                for err_name, err_bit in self.error_mapping.items():                    if self.sys_error & (1 << err_bit) != 0:                        self.error_detail.insert(customtkinter.END, err_name + '\n')                self.error_detail.configure(state='disabled')                if self.sys_error == 0:                    self.error_indicator.configure(text="No Error", state='disabled', fg_color='green', text_color_disabled='white')                else:                    self.error_indicator.configure(text="Pending Error", state='disabled', fg_color='red', text_color_disabled='white')        def clear_error_callback(self):            self.sender(f'CLREER')            self.sys_error = 0    class SystemMessage:        class InputMsgLine:            def __init__(self, frame: customtkinter.CTkFrame, name: str, fields: list[tuple[str, customtkinter.CTkBaseClass | None]]):                self.lock = threading.Lock()                self.time_line: str = ''                self.fields_var: dict[str, str] = {n: "" for n, _ in fields}                self.frame = customtkinter.CTkFrame(frame)                self.frame.pack(side=customtkinter.TOP, padx=10, pady=10, anchor='nw', fill=customtkinter.X, expand=True)                customtkinter.CTkLabel(self.frame, text=name).grid(row=0, column=0, rowspan=len(fields) + 1, padx=10, pady=5, sticky="w")                customtkinter.CTkLabel(self.frame, text="Message Time", width=200, anchor="e").grid(row=0, column=1, padx=10, pady=5)                self.time_var = customtkinter.StringVar(self.frame, '')                customtkinter.CTkEntry(self.frame, textvariable=self.time_var, state='disabled', width=120, justify="center").grid(row=0, column=2, padx=10, pady=5)                self.vars = {}                for i, (name, field) in enumerate(fields):                    customtkinter.CTkLabel(self.frame, text=name, width=200, anchor="e").grid(row=i + 1, column=1, padx=10, pady=5, sticky="e")                    if field is not None:                        field.grid(row=0, column=2, padx=10, pady=5)                    else:                        self.vars[name] = customtkinter.StringVar(self.frame, '')                        customtkinter.CTkEntry(self.frame, textvariable=self.vars[name], state='disabled', width=120, justify="center").grid(row=i + 1, column=2, padx=10, pady=5)            def __call__(self, date_time: datetime.datetime | None, curr_time: float, fields: dict[str, str]):                with self.lock:                    self.time_line = f"{date_time:%H:%M:%S.%f}"[:-1] if date_time is not None else f"{curr_time:.5f}"                    self.fields_var.update(fields)            def update(self):                self.time_var.set(self.time_line)                for name, field in self.fields_var.items():                    if name in self.vars:                        self.vars[name].set(field)        def __init__(self, frame: customtkinter.CTkFrame):            self.msg_second = App.SystemMessage.InputMsgLine(                frame, "Second End", [                    ('Previous Second Index', None),                    ('Clock Cycle Count', None)                ]            )            self.msg_pulse = App.SystemMessage.InputMsgLine(                frame, 'Pulse Input', [                    ('OverAll Phase Error (ns)', None),                    ('Observed Clock/Pulse', None),                    ('New System Clock/Pulse', None),                    ('Absolute Phase Error (ns)', None),                    ('Clock Difference (ns)', None),                ]            )            self.msg_rtc_update = App.SystemMessage.InputMsgLine(                frame, "RTC Update", [                    ('UTC shift', None),                    ('prediv_s', None),                    ('ss_shift', None),                    ('calibration', None)                ]            )            self.msg_utc_input = App.SystemMessage.InputMsgLine(                frame, 'UTC Input', [                    ('Input UTC Date', None),                    ('Input UTC Time', None),                ]            )        def __call__(self, msg_type: str, fields: tuple[str, ...], date_time: datetime.datetime, curr_time: float, clock: int, tick: int, sub_tick: int, tick_frac: int):            match msg_type, fields:                case 'SECON', (prev_second, ):                    self.msg_second(date_time, curr_time, {'Previous Second Index': str(int(prev_second)), 'Clock Cycle Count': str(clock)})                case 'PULSE', (prev_clk_per_pulse, curr_clk_per_pulse):                    curr_clk_per_pulse, sub_clk = curr_clk_per_pulse.split('+')                    sub_clk = sub_clk.split('/')                    curr_clk_per_pulse = int(curr_clk_per_pulse) + int(sub_clk[0]) / int(sub_clk[1])                    self.msg_pulse(                        date_time, curr_time, {                            'OverAll Phase Error (ns)': f'{(((sub_tick - tick_frac) if tick + 1 == TICKS_PER_SECOND else (clock - curr_clk_per_pulse)) if clock > curr_clk_per_pulse / 2 else clock) / curr_clk_per_pulse * 1e9:+07.2f}',                            'Observed Clock/Pulse': str(int(prev_clk_per_pulse)),                            'New System Clock/Pulse': f"{curr_clk_per_pulse:.2f}",                            'Absolute Phase Error (ns)': f'{((clock - curr_clk_per_pulse) if clock > curr_clk_per_pulse / 2 else clock) / curr_clk_per_pulse * 1e9:+07.2f}',                            'Clock Difference (ns)': f"{(curr_clk_per_pulse - int(prev_clk_per_pulse)) / curr_clk_per_pulse * 1e9:+07.2f}",                        }                    )                case 'RTCUP', (utc_shift, prediv_s, ss_shift, calibration):                    self.msg_rtc_update(                        date_time, curr_time, {                            'UTC shift': str(int(utc_shift)),                            'prediv_s': str(int(prediv_s)),                            'ss_shift': f"{int(ss_shift):+d}",                            'calibration': f"{int(calibration):+d}"}                    )                case 'UTCIN', (utc_date, utc_time):                    self.msg_utc_input(                        date_time, curr_time, {                            'Input UTC Date': utc_date,                            'Input UTC Time': utc_time,                        }                    )        def update(self):            self.msg_second.update()            self.msg_pulse.update()            self.msg_rtc_update.update()            self.msg_utc_input.update()    class EventRecord:        def __init__(self, frame: customtkinter.CTkFrame, title: str, channel_num: int):            self.lock = threading.Lock()            self.channel_num = channel_num            plt.ion()            self.event_frame = packed_frame(frame)            customtkinter.CTkLabel(self.event_frame, text=title).pack(padx=10, pady=5, fill=customtkinter.X)            stat_frame = packed_frame(self.event_frame)            self.stat_select = customtkinter.CTkOptionMenu(stat_frame, values=[f"CH_{i + 1}" for i in range(self.channel_num)])            self.stat_select.pack(side=customtkinter.LEFT, padx=10, pady=10)            customtkinter.CTkLabel(stat_frame, text="freq:").pack(side=customtkinter.LEFT, padx=10, pady=10)            self.freq_var = customtkinter.StringVar(stat_frame, '')            customtkinter.CTkEntry(stat_frame, textvariable=self.freq_var, state='disabled', width=120, justify="center").pack(side=customtkinter.LEFT, padx=10, pady=10)            customtkinter.CTkLabel(stat_frame, text="duty:").pack(side=customtkinter.LEFT, padx=10, pady=10)            self.duty_var = customtkinter.StringVar(stat_frame, '')            customtkinter.CTkEntry(stat_frame, textvariable=self.duty_var, state='disabled', width=120, justify="center").pack(side=customtkinter.LEFT, padx=10, pady=10)            plot_select_frame = packed_frame(self.event_frame)            self.plot_select = []            for i in range(self.channel_num):                self.plot_select.append(customtkinter.CTkCheckBox(plot_select_frame, text=f"CH_{i + 1}", onvalue=True, offvalue=False))                self.plot_select[-1].grid(row=i // 6, column=i % 6, sticky=customtkinter.W, padx=10, pady=10)                if i < 10:                    self.plot_select[-1].select()                else:                    self.plot_select[-1].deselect()            fig = plt.figure(figsize=(12, 6))            self.ax = fig.add_subplot(1, 1, 1)            self.ax.axis('off')            fig.tight_layout(pad=0)            fig.subplots_adjust(wspace=0, hspace=0)            self.canvas = plt_tk.FigureCanvasTkAgg(fig, master=self.event_frame)            self.canvas.get_tk_widget().configure(height=150, width=600)            self.canvas.draw()            self.canvas.get_tk_widget().pack(padx=10, pady=10, fill=customtkinter.X, expand=True)            self.time = [[] for _ in range(self.channel_num)]            self.value = [[] for _ in range(self.channel_num)]            self.last_rise_time: list[float | None] = [None for _ in range(self.channel_num)]            self.last_fall_time: list[float | None] = [None for _ in range(self.channel_num)]            self.ema_freq: list[float] = [0 for _ in range(self.channel_num)]            self.ema_duty: list[float] = [0 for _ in range(self.channel_num)]            self.last_record_host_time: float = time.time()            self.last_record_device_time: float = 0        def reset(self):            self.time = [[] for _ in range(self.channel_num)]            self.value = [[] for _ in range(self.channel_num)]            self.last_rise_time = [None for _ in range(self.channel_num)]            self.last_fall_time = [None for _ in range(self.channel_num)]            self.ema_freq = [0 for _ in range(self.channel_num)]            self.ema_duty = [0 for _ in range(self.channel_num)]            self.last_record_host_time = time.time()            self.last_record_device_time = 0            self.ax.clear()            self.ax.axis('off')            self.canvas.draw()        def update_time(self, curr_time: float):            with self.lock:                self.last_record_host_time = time.time()                self.last_record_device_time = max(self.last_record_device_time, curr_time)        def __call__(self, channel: int, curr_time: float, edge: str):            curr_val = {'R': 1, 'F': 0, 'RX': .5, 'FX': .5}[edge]            prev_val = {'R': 0, 'F': 1, 'RX': 0, 'FX': 1}[edge]            self.update_time(curr_time)            with self.lock:                self.time[channel] += [curr_time, curr_time]                self.value[channel] += [prev_val, curr_val]                # update statistic                if edge in ['R', 'RX'] and self.last_rise_time[channel] is not None and self.last_fall_time[channel] is not None:                    self.ema_freq[channel] = (1 - STAT_UPDATE_RATE) * self.ema_freq[channel] + STAT_UPDATE_RATE * 1 / (curr_time - self.last_rise_time[channel])                    self.ema_duty[channel] = (1 - STAT_UPDATE_RATE) * self.ema_duty[channel] + STAT_UPDATE_RATE * (self.last_fall_time[channel] - self.last_rise_time[channel]) / (curr_time - self.last_rise_time[channel])                # record last edge for statistic                if edge in ['RX', 'FX']:                    self.last_rise_time[channel] = None                    self.last_fall_time[channel] = None                elif edge == 'R':                    self.last_rise_time[channel] = curr_time                    self.last_fall_time[channel] = None                else:                    self.last_fall_time[channel] = curr_time        def update(self):            self.ax.clear()            with self.lock:                channel = int(self.stat_select.get()[3:]) - 1                self.freq_var.set(f"{self.ema_freq[channel]:6.1f}Hz")                self.duty_var.set(f"{self.ema_duty[channel]:6.2%}")                curr_device_time = time.time() - self.last_record_host_time + self.last_record_device_time                min_t = curr_device_time - 3                self.ax.set_xlim(min_t, curr_device_time)                MAX_BUFFER = TICKS_PER_SECOND                plot_legend = False                for i in range(self.channel_num):                    self.time[i] = self.time[i][-MAX_BUFFER:]                    self.value[i] = self.value[i][-MAX_BUFFER:]                    if self.ema_freq[i] > 200:                        self.plot_select[i].deselect()                        self.plot_select[i].configure(state='disabled')                    else:                        self.plot_select[i].configure(state='normal')                    if self.plot_select[i].get():                        self.ax.plot(self.time[i], self.value[i], label=f'CH_{i + 1}', alpha=0.5, linewidth=1)                        plot_legend = True            self.ax.axis('off')            if plot_legend:                self.ax.legend(loc='upper left', fontsize='xx-small')            self.canvas.draw()    class ConfigSystem:        @staticmethod        def get_is_digit(limit: int | None = None):            def is_digit(val: str) -> bool:                return str(val) == '' or (str.isdigit(val) and (limit is None or int(val) < 2 ** limit))            return is_digit        @staticmethod        def get_is_num(limit: int | None = None):            f = App.ConfigSystem.get_is_digit(None if limit is None else limit - 1)            def is_num(val: str) -> bool:                return f(val) or (str(val).startswith('-') and f(val[1:]))            return is_num        class TimerCaptureConfig:            def __init__(self, frame: customtkinter.CTkFrame, timer_num: int, sender):                self.sender = sender                customtkinter.CTkLabel(frame, text="Timer Capture Config").pack(padx=10, pady=5, fill=customtkinter.X)                basic_line = packed_frame(frame, show=False, anchor='w')                self.channel = customtkinter.CTkOptionMenu(basic_line, values=[f"CH_{i + 1}" for i in range(timer_num)])                self.channel.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(basic_line, text="pre_divider").pack(side=customtkinter.LEFT, padx=10, pady=10, fill=customtkinter.X)                self.pre_divider = customtkinter.CTkEntry(basic_line, placeholder_text='0', validate='all', validatecommand=(basic_line.register(App.ConfigSystem.get_is_digit(32)), '%P'))                self.pre_divider.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(basic_line, text="shift").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.shift = customtkinter.CTkEntry(basic_line, placeholder_text='0', validate='all', validatecommand=(basic_line.register(App.ConfigSystem.get_is_num(32)), '%P'))                self.shift.pack(side=customtkinter.LEFT, padx=10, pady=10)                timer_button_line = packed_frame(frame, show=False, anchor='w')                customtkinter.CTkLabel(timer_button_line, text="Align with Second").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.align = customtkinter.CTkSegmentedButton(timer_button_line, values=['No Align', 'Align to Second', 'Align & Drop last'])                self.align.set('No Align')                self.align.pack(side=customtkinter.LEFT, padx=10, pady=10)                self.send = customtkinter.CTkButton(timer_button_line, text='Send', command=self.send_config)                self.send.pack(side=customtkinter.LEFT, padx=10, pady=10)            def disable(self):                self.enable('disabled')            def enable(self, state='normal'):                self.channel.configure(state=state)                self.pre_divider.configure(state=state)                self.shift.configure(state=state)                self.align.configure(state=state)                self.send.configure(state=state)            def send_config(self):                channel = int(self.channel.get()[3:])                pre_divider = self.pre_divider.get()                pre_divider = int(pre_divider) if len(pre_divider) > 0 else 0                shift = self.shift.get()                shift = int(shift) if len(shift) > (1 if shift.startswith('-') else 0) else 0                flags = {'No Align': 'N', 'Align to Second': 'A', 'Align & Drop last': 'D'}[self.align.get()]                self.sender(f'CONFIG,TIMEC,{channel},{pre_divider},{shift},{flags}')        class OutputTriggerConfig:            def __init__(self, frame: customtkinter.CTkFrame, trigger_num: int, sender):                self.sender = sender                customtkinter.CTkLabel(frame, text="Output Trigger Config").pack(padx=10, pady=5, fill=customtkinter.X)                basic_line = packed_frame(frame, show=False, anchor='w')                self.channel = customtkinter.CTkOptionMenu(basic_line, values=[f"CH_{i + 1}" for i in range(trigger_num)])                self.channel.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(basic_line, text="pulse width").pack(side=customtkinter.LEFT, padx=0, pady=10, fill=customtkinter.X)                self.pulse_width = customtkinter.CTkEntry(basic_line, placeholder_text='0', validate='all', width=100, validatecommand=(basic_line.register(App.ConfigSystem.get_is_digit(16)), '%P'))                self.pulse_width.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(basic_line, text="dead zone").pack(side=customtkinter.LEFT, padx=0, pady=10)                self.pulse_deadz = customtkinter.CTkEntry(basic_line, placeholder_text='0', validate='all', width=90, validatecommand=(basic_line.register(App.ConfigSystem.get_is_digit(16)), '%P'))                self.pulse_deadz.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(basic_line, text="RF compensation").pack(side=customtkinter.LEFT, padx=0, pady=10)                self.pulse_rf = customtkinter.CTkEntry(basic_line, placeholder_text='0', validate='all', width=90, validatecommand=(basic_line.register(App.ConfigSystem.get_is_num(16)), '%P'))                self.pulse_rf.pack(side=customtkinter.LEFT, padx=10, pady=10)                mask_frame = packed_frame(frame)                customtkinter.CTkLabel(mask_frame, text="signal masks setup").pack(padx=10, pady=10, fill=customtkinter.X)                self.masks: list[int] = [0 for _ in range(SIGNAL_MASK_SIZE)]                self.masks_var = customtkinter.StringVar(frame, '')                mask_bit_line = packed_frame(mask_frame, show=False, anchor='w')                customtkinter.CTkLabel(mask_bit_line, text="signal bit").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.bit_bias = customtkinter.CTkOptionMenu(mask_bit_line, values=["Input", "Timer", "Output", "Relay"], width=100)                self.bit_bias.set("Timer")                self.bit_bias.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(mask_bit_line, text="+").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.edit_bit = customtkinter.CTkEntry(                    mask_bit_line, placeholder_text='0', width=60,                    validate='all', validatecommand=(basic_line.register(lambda v: App.ConfigSystem.get_is_digit()(v) and (str(v) == '' or (0 <= int(v) < 64 * SIGNAL_MASK_SIZE))), '%P')                )                self.edit_bit.pack(side=customtkinter.LEFT, padx=10, pady=10)                self.mask_set_button = customtkinter.CTkButton(mask_bit_line, text="SET", width=100, command=self.bit_set_callback)                self.mask_clear_button = customtkinter.CTkButton(mask_bit_line, text="CLEAR", width=100, command=self.bit_clear_callback)                self.mask_clearall_button = customtkinter.CTkButton(mask_bit_line, text="CLEAR ALL", width=100, command=self.bit_clearall_callback)                self.mask_set_button.pack(side=customtkinter.LEFT, padx=5, pady=10)                self.mask_clear_button.pack(side=customtkinter.LEFT, padx=5, pady=10)                self.mask_clearall_button.pack(side=customtkinter.LEFT, padx=5, pady=10)                customtkinter.CTkEntry(mask_frame, textvariable=self.masks_var, width=700, state='disabled', justify="center").pack(padx=10, pady=10)                signal_in_pulse_line = packed_frame(frame, show=False, anchor='w')                customtkinter.CTkLabel(signal_in_pulse_line, text="signal in pulse").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.pulse_align = customtkinter.CTkSegmentedButton(signal_in_pulse_line, values=['Drop Signal', 'Stop Pulse', 'Expand Pulse Width', 'Align Fall Edge'])                self.pulse_align.set('Drop Signal')                self.pulse_align.pack(side=customtkinter.LEFT, padx=10, pady=10)                customtkinter.CTkLabel(signal_in_pulse_line, text="polarity").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.pulse_polarity = customtkinter.CTkSegmentedButton(signal_in_pulse_line, values=['HIGH', 'LOW'])                self.pulse_polarity.set('HIGH')                self.pulse_polarity.pack(side=customtkinter.LEFT, padx=10, pady=10)                signal_in_deadz_line = packed_frame(frame, show=False, anchor='w')                customtkinter.CTkLabel(signal_in_deadz_line, text="signal in dead zone").pack(side=customtkinter.LEFT, padx=10, pady=10)                self.deadz_align = customtkinter.CTkSegmentedButton(signal_in_deadz_line, values=['Drop Signal', 'Pending Pulse', 'Align to Last Fall', 'Align to First Fall'])                self.deadz_align.set('Drop Signal')                self.deadz_align.pack(side=customtkinter.LEFT, padx=10, pady=10)                self.send = customtkinter.CTkButton(signal_in_deadz_line, text='Send', command=self.send_config)                self.send.pack(side=customtkinter.LEFT, padx=10, pady=10)                self.update_masks()            def disable(self):                self.enable('disabled')            def enable(self, state='normal'):                self.channel.configure(state=state)                self.pulse_width.configure(state=state)                self.pulse_deadz.configure(state=state)                self.pulse_rf.configure(state=state)                self.bit_bias.configure(state=state)                self.edit_bit.configure(state=state)                self.mask_set_button.configure(state=state)                self.mask_clear_button.configure(state=state)                self.mask_clearall_button.configure(state=state)                self.pulse_align.configure(state=state)                self.deadz_align.configure(state=state)                self.pulse_polarity.configure(state=state)                self.send.configure(state=state)            def update_masks(self):                self.masks_var.set(', '.join(f"{mask:016X}" for mask in reversed(self.masks)))            def get_bit(self):                return {"Input": 0, "Timer": 192, "Output": 128, "Relay": 256}[self.bit_bias.get()] + (int(self.edit_bit.get()) if str(self.edit_bit.get()) != '' else 0)            def bit_set_callback(self):                bit = self.get_bit()                self.masks[bit // 64] |= 1 << (bit % 64)                self.update_masks()            def bit_clear_callback(self):                bit = self.get_bit()                self.masks[bit // 64] &= ~(1 << (bit % 64))                self.masks[bit // 64] &= ~(1 << (bit % 64))                self.update_masks()            def bit_clearall_callback(self):                for i in range(len(self.masks)):                    self.masks[i] = 0                self.update_masks()            def send_config(self):                channel = int(self.channel.get()[3:])                pulse_width = self.pulse_width.get()                pulse_width = int(pulse_width) if len(pulse_width) > 0 else 0                pulse_deadz = self.pulse_deadz.get()                pulse_deadz = int(pulse_deadz) if len(pulse_deadz) > 0 else 0                pulse_rf = self.pulse_rf.get()                pulse_rf = int(pulse_rf) if len(pulse_rf) > 0 else 0                checksum: int = 0xAAAAAAAAAAAAAAAA                for mask in self.masks:                    checksum = (checksum ^ mask) & (2 ** 64 - 1)                polarity = {'HIGH': 'H', 'LOW': 'L'}[self.pulse_polarity.get()]                flags = {'Drop Signal': 'D', 'Stop Pulse': 'S', 'Expand Pulse Width': 'E', 'Align Fall Edge': 'F'}[self.pulse_align.get()] + \                        {'Drop Signal': 'D', 'Pending Pulse': 'P', 'Align to Last Fall': 'L', 'Align to First Fall': 'F'}[self.deadz_align.get()]                self.sender(f'CONFIG,TRIGR,{channel},{pulse_width},{pulse_deadz},{pulse_rf},' + ','.join(f"{mask:016X}" for mask in self.masks) + f',{checksum:016X},{polarity},{flags}')        class Control:            def __init__(self, frame: customtkinter.CTkFrame, sender):                self.sender = sender                customtkinter.CTkLabel(frame, text="System Control").pack(padx=10, pady=5, fill=customtkinter.X)                button_line = packed_frame(frame, show=False)                self.reset_all_button = customtkinter.CTkButton(button_line, text="RESET ALL", width=100, command=self.reset_all_callback)                self.reset_backup_button = customtkinter.CTkButton(button_line, text="RESET BACKUP", width=100, command=self.reset_backup_callback)                self.reboot_button = customtkinter.CTkButton(button_line, text="REBOOT", width=100, command=self.reset_callback)                self.save_button = customtkinter.CTkButton(button_line, text="SAVE to FLASH", command=self.save_callback)                self.reset_all_button.pack(side=customtkinter.LEFT, padx=5, pady=10)                self.reset_backup_button.pack(side=customtkinter.LEFT, padx=5, pady=10)                self.reboot_button.pack(side=customtkinter.LEFT, padx=5, pady=10, fill=customtkinter.X)                self.save_button.pack(side=customtkinter.LEFT, padx=5, pady=10, fill=customtkinter.X)            def disable(self):                self.enable('disabled')            def enable(self, state='normal'):                self.reset_all_button.configure(state=state)                self.reset_backup_button.configure(state=state)                self.reboot_button.configure(state=state)                self.save_button.configure(state=state)            def reset_all_callback(self):                self.sender(f'RSTALL')            def reset_backup_callback(self):                self.sender(f'BKURST')            def reset_callback(self):                self.sender(f'REBOOT')            def save_callback(self):                self.sender(f'SAVCFG')        def __init__(self, frame: customtkinter.CTkFrame, timer_num: int, trigger_num: int, sender):            self.lock = threading.Lock()            self.timer_config = App.ConfigSystem.TimerCaptureConfig(packed_frame(frame), timer_num, sender)            self.trigger_config = App.ConfigSystem.OutputTriggerConfig(packed_frame(frame), trigger_num, sender)            self.control = App.ConfigSystem.Control(packed_frame(frame), sender)            self.disable()        def enable(self):            self.timer_config.enable()            self.trigger_config.enable()            self.control.enable()        def disable(self):            self.timer_config.disable()            self.trigger_config.disable()            self.control.disable()    def __init__(self):        super().__init__()        self.title("Digital PLL")        self.geometry("1400x870")        # system information panel        self.system_frame = customtkinter.CTkFrame(self, fg_color="transparent")        self.system_frame.pack(side=customtkinter.LEFT, anchor='ne', padx=10, pady=10)        self.connection = App.Connection(packed_frame(self.system_frame), self.parser_thread, self.connect_callback, self.disconnect_callback)        self.transmit_stat = App.TransmitStatistic(packed_frame(self.system_frame))        self.system_time = App.CurrentTime(packed_frame(self.system_frame))        self.system_state = App.SystemState(packed_frame(self.system_frame))        self.system_error = App.SystemError(packed_frame(self.system_frame), self.connection.send)        # main workspace        self.workspace = customtkinter.CTkTabview(master=self)        self.workspace.pack(side=customtkinter.LEFT, padx=10, pady=10, anchor='nw', fill=customtkinter.X, expand=True)        self.workspace.add('System Message')        self.workspace.add('Capture & Trigger')        self.workspace.add('System Config')        self.system_message = App.SystemMessage(packed_frame(self.workspace.tab('System Message')))        trigger_capture_frame = packed_frame(self.workspace.tab('Capture & Trigger'))        self.trigger_recorder = App.EventRecord(trigger_capture_frame, 'Output Trigger', OUTPUT_TRIGGER_CHANNEL_NUM)        self.capture_recorder = App.EventRecord(trigger_capture_frame, 'Input Capture', INPUT_CAPTURE_CHANNEL_NUM)        self.config = App.ConfigSystem(packed_frame(self.workspace.tab('System Config')), TIMER_CAPTURE_CHANNEL_NUM, OUTPUT_TRIGGER_CHANNEL_NUM, self.connection.send)        self.after(GUI_REFRESH_DELAY, self.gui_update)    def connect_callback(self):        self.config.enable()        self.system_error.enable()    def disconnect_callback(self):        self.config.disable()        self.system_error.disable()        self.transmit_stat.reset()        self.system_time.reset()        self.system_state.reset()        self.system_error.reset()        self.trigger_recorder.reset()        self.capture_recorder.reset()    def parser_thread(self, line: bytes) -> None:        line: str = line.decode('ascii').strip()        if len(line) <= 4 or line[0] != '$' or line[-3] != '*':            return        payload = line[1:-3]        checksum: int = 0        for b in payload.encode():            checksum = (checksum ^ b) & 0xff        if int(line[-2:], 16) != checksum:            return        msg_type, msg_idx, sys_state, _, _, timestamp, second, tick, sub_tick, clock, *fields = payload.split(',')        msg_idx, sys_state, second, tick, (sub_tick, tick_frac), clock = int(msg_idx), int(sys_state, 16), int(second), int(tick), sub_tick.split('/'), int(clock)        sub_tick, tick_frac = int(sub_tick), int(tick_frac)        sub_second = (tick + sub_tick / tick_frac) / TICKS_PER_SECOND        date_time = datetime.datetime.utcfromtimestamp(int(timestamp) + sub_second) if len(timestamp) > 0 else None        curr_time = second + sub_second        self.transmit_stat(msg_idx)        self.system_time(date_time, curr_time)        self.system_state(sys_state)        self.trigger_recorder.update_time(curr_time)        self.capture_recorder.update_time(curr_time)        match msg_type, fields:            case 'SECON' | 'PULSE' | 'RTCUP' | 'UTCIN', *_:                self.system_message(msg_type, fields, date_time, curr_time, int(clock), tick, sub_tick, tick_frac)            case 'TROUT', (channel, edge, rf):                self.trigger_recorder(int(channel) - 1, curr_time + 1 / TICKS_PER_SECOND, edge)            case 'CAPIN', (channel, edge):                self.capture_recorder(int(channel) - 1, curr_time, edge)            case 'RSPON', (state, id):                print(line)                if state == 'OK':                    self.config.enable()            case 'ERROR', (flag, ):                self.system_error(int(flag, 16))    def gui_update(self):        self.transmit_stat.update()        self.system_time.update()        self.system_state.update()        self.system_error.update()        self.system_message.update()        self.trigger_recorder.update()        self.capture_recorder.update()        self.after(GUI_REFRESH_DELAY, self.gui_update)app = App()app.mainloop()